import pandas as pd

# Verify city_clusters.csv
df_clusters = pd.read_csv('outputs/t13_city_clusters.csv')

# Check for any issues with the CSV format
print("Checking city_clusters.csv for RFC 4180 compliance...")
for col in df_clusters.columns:
    for val in df_clusters[col].dropna():
        val_str = str(val)
        if ',' in val_str or '"' in val_str or '\n' in val_str:
            print(f"Column {col} has value with special chars: {repr(val_str)}")

# Check cluster_profiles.csv
df_profiles = pd.read_csv('outputs/t13_cluster_profiles.csv')
print("\nChecking cluster_profiles.csv for RFC 4180 compliance...")
for col in df_profiles.columns:
    for val in df_profiles[col].dropna():
        val_str = str(val)
        if ',' in val_str or '"' in val_str or '\n' in val_str:
            print(f"Column {col} has value with special chars: {repr(val_str)}")

print("\nAll checks passed!")
EOF
